    struct LifetimeResourceManagerDispatch final : tTJSDispatch {
        explicit LifetimeResourceManagerDispatch(
            LoadResultLifetimeState &value) : state(value) {}

        tjs_error FuncCall(tjs_uint32, const tjs_char *membername,
                           tjs_uint32 *, tTJSVariant *result,
                           tjs_int numparams, tTJSVariant **param,
                           iTJSDispatch2 *) override {
            if(!membername || TJS_strcmp(membername, TJS_W("findMotion")) ||
               numparams != 2 || !param || !param[1]) {
                return TJS_E_MEMBERNOTFOUND;
            }
            state.requestedPaths.emplace_back(ttstr(*param[1]));
            state.requestedContexts.emplace_back(
                param[0] ? *param[0] : tTJSVariant());

            auto *motionDispatch = new LifetimeMotionDispatch(state);
            tTJSVariant motionValue(motionDispatch, motionDispatch);
            motionDispatch->Release();

            auto *loadResult = new LifetimeLoadResultDispatch(
                state, std::move(motionValue));
            if(result) {
                *result = tTJSVariant(loadResult, loadResult);
            }
            loadResult->Release();
            return TJS_S_OK;
        }

        LoadResultLifetimeState &state;
    };

