    struct ControllerMetadataAccessorProbe final : tTJSDispatch {
        struct Read {
            ttstr member;
            tjs_uint32 flags{};
            tjs_uint32 *hint{};
            iTJSDispatch2 *objthis{};
        };

        ControllerMetadataAccessorProbe(tTJSVariant edgeValue,
                                        tTJSVariant nodeValue) :
            edge(std::move(edgeValue)), node(std::move(nodeValue)) {}

        tjs_error PropGet(tjs_uint32 flags,
                          const tjs_char *membername,
                          tjs_uint32 *hint, tTJSVariant *result,
                          iTJSDispatch2 *objthis) override {
            reads.push_back({ttstr(membername), flags, hint, objthis});
            if(!membername || !result) {
                return TJS_E_MEMBERNOTFOUND;
            }

            if(!TJS_strcmp(membername, TJS_W("beginFrame"))) {
                *result = static_cast<tjs_int>(12);
            } else if(!TJS_strcmp(membername, TJS_W("endFrame"))) {
                *result = static_cast<tjs_int>(18);
            } else if(!TJS_strcmp(
                          membername, TJS_W("blinkIntervalMin"))) {
                *result = 20.5;
            } else if(!TJS_strcmp(
                          membername, TJS_W("blinkIntervalMax"))) {
                *result = 40.25;
            } else if(!TJS_strcmp(
                          membername, TJS_W("blinkFrameCount"))) {
                *result = 6.75;
            } else if(!TJS_strcmp(membername, TJS_W("blinkEnabled"))) {
                *result = true;
            } else if(!TJS_strcmp(membername, TJS_W("edge"))) {
                *result = edge;
            } else if(!TJS_strcmp(membername, TJS_W("node"))) {
                *result = node;
            } else {
                return TJS_E_MEMBERNOTFOUND;
            }

            // ncbPropAccessor::GetValue deliberately ignores an ordinary
            // getter failure and converts the Variant written above.
            return TJS_E_FAIL;
        }

        tTJSVariant edge;
        tTJSVariant node;
        std::vector<Read> reads;
    };

